/**
 * build-tailwind.ts — the `tailwind` build path (S6).
 *
 * The landing HTML and `script.js` are compiled with the `tailwindcss` 3.4 library through
 * `postcss`, in process. Nothing generated by the model is executed: the CSS is produced by
 * Tailwind's own engine from the classes it finds in the two raw content sources, and the inline
 * `tailwind.config` object is *read* with a JSON5 parser (`JSON5.parse`, never
 * `eval`/`Function`/`vm`). Only `theme` and `darkMode` survive from that object, as plain JSON
 * data; `plugins`, `presets`, `content`, `important`, `prefix` and anything else are dropped, so
 * a model cannot inject plugins, prefixes, file globs or JS.
 *
 * `prepareTailwind` returns the HTML without the CDN script and without the inline config script
 * (plus exactly one `styles.css` link) and the minified CSS to prepend to `styles.css`.
 *
 * Every rejection is a 422: `TAILWIND_CONFIG_UNSUPPORTED` (config that is not limitable to
 * `theme`/`darkMode`, or a CDN plugin request), `BUILD_INPUT_TOO_LARGE` (HTML + JS over 1 MB) and
 * `TAILWIND_COMPILE_FAILED` (Tailwind itself blew up). The build runs per request and pays the
 * heavy limiter, so the input cap keeps a huge body from pinning a CPU.
 */

import * as cheerio from "cheerio";
import JSON5 from "json5";
import postcss from "postcss";
import tailwindcss, { type Config } from "tailwindcss";
import { HttpError } from "@/lib/http";

/** Ceiling for the compiled sources: HTML + `script.js`, checked before touching Tailwind. */
export const MAX_TAILWIND_INPUT_BYTES = 1024 * 1024;
/** Ceiling for the inline config object literal; a bigger one is rejected, never scanned twice. */
export const MAX_CONFIG_CHARS = 50 * 1024;
/** Depth ceiling for the copied config data (a deep object cannot reach Tailwind). */
const MAX_CONFIG_DEPTH = 32;

export const TAILWIND_CDN_RE = /cdn\.tailwindcss\.com/i;

const CONFIG_KEY = "tailwind.config";
const TAILWIND_INPUT = "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n";
const STYLESHEET_HREF_RE = /^(?:\.\/)?styles\.css$/i;
/** Keys that would rewrite a prototype instead of describing a theme. */
const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);
const DARK_MODE_STRATEGIES = new Set(["media", "class", "selector", "variant"]);

export interface TailwindPrepareResult {
  /** `index.html` without the Tailwind CDN, without the inline config and linking styles.css. */
  html: string;
  /** Minified compiled CSS, to be prepended to `styles.css`. */
  css: string;
}

/** The subset of the inline config the build accepts. */
interface TailwindConfig {
  theme?: unknown;
  darkMode?: unknown;
}

function unsupported(reason: string): HttpError {
  return new HttpError(
    422,
    "La configuración de Tailwind no se puede procesar",
    "TAILWIND_CONFIG_UNSUPPORTED",
    { reason }
  );
}

/** True when the HTML pulls Tailwind from its CDN (mode auto-detection). */
export function usesTailwindCdn(html: string): boolean {
  const $ = cheerio.load(html);
  return $("script[src]")
    .toArray()
    .some((el) => TAILWIND_CDN_RE.test($(el).attr("src") ?? ""));
}

/**
 * Copies a parsed config into plain JSON data: only objects, arrays and primitives survive, and
 * `__proto__`/`constructor`/`prototype` keys and non-finite numbers are dropped. JSON5 cannot
 * produce functions, so this is a shape guard rather than a code guard.
 */
function toJsonData(value: unknown, depth = 0): unknown {
  if (depth > MAX_CONFIG_DEPTH) return undefined;
  if (Array.isArray(value)) {
    return value.map((item) => toJsonData(item, depth + 1)).filter((item) => item !== undefined);
  }
  if (value !== null && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value)) {
      if (FORBIDDEN_KEYS.has(key)) continue;
      const next = toJsonData(item, depth + 1);
      if (next !== undefined) out[key] = next;
    }
    return out;
  }
  if (typeof value === "string" || typeof value === "boolean" || value === null) return value;
  if (typeof value === "number") return Number.isFinite(value) ? value : undefined;
  return undefined;
}

/** `darkMode` as Tailwind accepts it (`"class"`, `"media"` or `["class", selector]`). */
function normalizeDarkMode(value: unknown): unknown {
  const strategies = Array.isArray(value) ? value : [value];
  if (strategies.length === 0 || strategies.length > 2) return undefined;
  if (!strategies.every((item) => typeof item === "string")) return undefined;
  if (!DARK_MODE_STRATEGIES.has(String(strategies[0]))) return undefined;
  return Array.isArray(value) ? [...strategies] : strategies[0];
}

/** The balanced `{...}` starting at `start`, with strings and comments skipped. */
function balancedObject(text: string, start: number): string {
  // Bounded window: an object literal that does not close within the cap is rejected instead of
  // being scanned to the end of a hostile script.
  const end = Math.min(text.length, start + MAX_CONFIG_CHARS);
  let depth = 0;
  let i = start;
  while (i < end) {
    const ch = text[i];
    if (ch === '"' || ch === "'" || ch === "`") {
      i++;
      while (i < end) {
        if (text[i] === "\\") {
          i += 2;
          continue;
        }
        if (text[i] === ch) {
          i++;
          break;
        }
        i++;
      }
      continue;
    }
    if (ch === "/" && text[i + 1] === "/") {
      const lineEnd = text.indexOf("\n", i + 2);
      i = lineEnd < 0 || lineEnd >= end ? end : lineEnd + 1;
      continue;
    }
    if (ch === "/" && text[i + 1] === "*") {
      const commentEnd = text.indexOf("*/", i + 2);
      i = commentEnd < 0 || commentEnd >= end ? end : commentEnd + 2;
      continue;
    }
    if (ch === "{") depth++;
    else if (ch === "}") {
      depth--;
      if (depth === 0) return text.slice(start, i + 1);
    }
    i++;
  }
  throw unsupported("inline config too large or unterminated");
}

/** The object literal text of `<script>tailwind.config = {...}</script>`, or null when absent. */
function configObjectText(source: string): string | null {
  const keyAt = source.indexOf(CONFIG_KEY);
  if (keyAt < 0) return null;
  let i = keyAt + CONFIG_KEY.length;
  // Only `tailwind.config = {...}` is supported: skip whitespace, require `=`, then the object.
  while (i < source.length && /\s/.test(source[i])) i++;
  if (source[i] !== "=") throw unsupported("tailwind.config is not an object literal");
  i++;
  while (i < source.length && /\s/.test(source[i])) i++;
  if (source[i] !== "{") throw unsupported("tailwind.config is not an object literal");
  return balancedObject(source, i);
}

/**
 * The inline config limited to `theme` + `darkMode`. Null when the landing has no inline config.
 * The object text is parsed as data; a real JS object (functions, `presets` requiring modules…)
 * simply fails to parse, which is the 422 `TAILWIND_CONFIG_UNSUPPORTED` contract.
 */
export function readInlineConfig(html: string): TailwindConfig | null {
  const $ = cheerio.load(html);
  let config: TailwindConfig | null = null;
  $("script:not([src])").each((_, el) => {
    if (config !== null) return;
    const text = $(el).text();
    const objectText = configObjectText(text);
    if (objectText === null) return;
    let parsed: unknown;
    try {
      parsed = JSON5.parse(objectText);
    } catch {
      throw unsupported("inline config is not JSON5");
    }
    if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
      throw unsupported("inline config is not an object");
    }
    const source = parsed as Record<string, unknown>;
    const limited: TailwindConfig = {};
    if (source.theme !== undefined) limited.theme = toJsonData(source.theme);
    const darkMode = normalizeDarkMode(source.darkMode);
    if (darkMode !== undefined) limited.darkMode = darkMode;
    config = limited;
  });
  return config;
}

/** True when a Tailwind CDN URL asks for plugins (`?plugins=forms,typography`). */
function cdnAsksForPlugins(src: string): boolean {
  const queryAt = src.indexOf("?");
  if (queryAt < 0) return false;
  for (const pair of src.slice(queryAt + 1).split("&")) {
    const eq = pair.indexOf("=");
    const name = (eq < 0 ? pair : pair.slice(0, eq)).trim();
    const value = eq < 0 ? "" : pair.slice(eq + 1).trim();
    if (name === "plugins" && value.length > 0) return true;
  }
  return false;
}

/**
 * Removes the Tailwind CDN script (any query string) and every inline script that carries
 * `tailwind.config`, then guarantees exactly one `styles.css` link. The CDN plugin query is
 * rejected: the `forms`/`typography` plugins live in their own packages, and S6 forbids adding
 * dependencies for them, so asking for them is answerable only with 422.
 */
export function stripTailwindAssets(html: string): string {
  const $ = cheerio.load(html);
  $("script[src]").each((_, el) => {
    const node = $(el);
    const src = (node.attr("src") ?? "").trim();
    if (!TAILWIND_CDN_RE.test(src)) return;
    if (cdnAsksForPlugins(src)) throw unsupported("CDN plugins are not available");
    node.remove();
  });
  $("script:not([src])").each((_, el) => {
    const node = $(el);
    if (node.text().includes(CONFIG_KEY)) node.remove();
  });

  let linked = false;
  $("link[href]").each((_, el) => {
    const node = $(el);
    const rel = (node.attr("rel") ?? "").trim().toLowerCase().split(/\s+/);
    if (!rel.includes("stylesheet")) return;
    if (!STYLESHEET_HREF_RE.test((node.attr("href") ?? "").trim())) return;
    if (linked) {
      node.remove();
      return;
    }
    linked = true;
    node.attr("href", "styles.css");
  });
  if (!linked) {
    const tag = '<link rel="stylesheet" href="styles.css">';
    const head = $("head").first();
    if (head.length > 0) head.append(tag);
    else $.root().prepend(tag);
  }

  return $.html();
}

/**
 * Collapses generated CSS to one line, keeping strings, `url()` and `/*! ... *\/` license banners
 * intact. Deliberately conservative: only whitespace between tokens is removed, so the result is
 * always valid CSS (re-parsed by the tests).
 */
export function minifyCss(css: string): string {
  const n = css.length;
  let out = "";
  let pendingSpace = false;
  let i = 0;
  const DROP_AROUND = "{};,:";
  // Space needed before `ch`, given the last emitted character.
  const needsSpace = (ch: string): boolean => {
    const prev = out[out.length - 1];
    if (!prev) return false;
    if (DROP_AROUND.includes(prev) || DROP_AROUND.includes(ch)) return false;
    return true;
  };

  while (i < n) {
    const ch = css[i];
    if (ch === "/" && css[i + 1] === "*") {
      const end = css.indexOf("*/", i + 2);
      const stop = end < 0 ? n : end + 2;
      // `/*! ... */` is a license banner: kept verbatim, everything else is dropped.
      if (css[i + 2] === "!") {
        if (pendingSpace && needsSpace(ch)) out += " ";
        out += css.slice(i, stop);
      }
      pendingSpace = true;
      i = stop;
      continue;
    }
    if (ch === '"' || ch === "'") {
      if (pendingSpace && needsSpace(ch)) out += " ";
      pendingSpace = false;
      const start = i;
      i++;
      while (i < n) {
        if (css[i] === "\\") {
          i += 2;
          continue;
        }
        if (css[i] === ch) {
          i++;
          break;
        }
        i++;
      }
      out += css.slice(start, i);
      continue;
    }
    // An unquoted `url(...)` may hold spaces; copy it verbatim.
    if ((ch === "u" || ch === "U") && /^url\(/i.test(css.slice(i, i + 4))) {
      if (pendingSpace && needsSpace(ch)) out += " ";
      pendingSpace = false;
      const start = i;
      i += 4;
      while (i < n) {
        if (css[i] === "\\") {
          i += 2;
          continue;
        }
        if (css[i] === ")") {
          i++;
          break;
        }
        i++;
      }
      out += css.slice(start, i);
      continue;
    }
    if (ch === " " || ch === "\t" || ch === "\n" || ch === "\r" || ch === "\f") {
      pendingSpace = true;
      i++;
      continue;
    }
    if (pendingSpace) {
      if (needsSpace(ch)) out += " ";
      pendingSpace = false;
    }
    out += ch;
    i++;
  }

  return out.trim();
}

/** Compiles the Tailwind layers for the given sources, with our own config only. */
async function runTailwind(
  html: string,
  script: string,
  config: TailwindConfig | null
): Promise<string> {
  // `content`, `corePlugins` and `plugins` are ours and never come from the model.
  const tailwindConfig: Config = {
    content: [
      { raw: html, extension: "html" },
      { raw: script, extension: "js" },
    ],
  };
  // `theme`/`darkMode` are plain JSON copied by `toJsonData`/`normalizeDarkMode`.
  if (config?.theme !== undefined) tailwindConfig.theme = config.theme as Config["theme"];
  if (config?.darkMode !== undefined) tailwindConfig.darkMode = config.darkMode as Config["darkMode"];

  try {
    const result = await postcss([tailwindcss(tailwindConfig)]).process(TAILWIND_INPUT, {
      from: undefined,
    });
    return minifyCss(result.css);
  } catch {
    throw new HttpError(422, "No se pudo compilar Tailwind", "TAILWIND_COMPILE_FAILED");
  }
}

/**
 * Prepares the Tailwind path: input cap, inline config (data only), CDN/config stripping and the
 * in-process compile. Throws `HttpError` 422 on every rejection.
 */
export async function prepareTailwind(
  html: string,
  script: string
): Promise<TailwindPrepareResult> {
  const totalBytes = Buffer.byteLength(html, "utf8") + Buffer.byteLength(script, "utf8");
  if (totalBytes > MAX_TAILWIND_INPUT_BYTES) {
    throw new HttpError(
      422,
      "La landing es demasiado grande para compilar Tailwind",
      "BUILD_INPUT_TOO_LARGE",
      { maxBytes: MAX_TAILWIND_INPUT_BYTES, bytes: totalBytes }
    );
  }

  const config = readInlineConfig(html);
  const strippedHtml = stripTailwindAssets(html);
  const css = await runTailwind(strippedHtml, script, config);
  return { html: strippedHtml, css };
}
